import socket
import time
import os
import sys

def get_env_var(name, default=None):
    return os.environ.get(name, default)

def connect_with_retry(host, port, max_attempts=5, retry_interval=2):
    attempt = 0
    while attempt < max_attempts:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(5)
            sock.connect((host, port))
            sock.close()
            print(f"Successfully connected to {host}:{port}")
            return True
        except (socket.timeout, socket.error, OSError) as e:
            attempt += 1
            print(f"Connection attempt {attempt} failed: {e}")
            if attempt < max_attempts:
                print(f"Retrying in {retry_interval} seconds...")
                time.sleep(retry_interval)
            else:
                print(f"Failed to connect to {host}:{port} after {max_attempts} attempts.")
                return False

if __name__ == "__main__":
    host = get_env_var("TARGET_HOST", "127.0.0.1")
    port_str = get_env_var("TARGET_PORT", "80")

    try:
        port = int(port_str)
    except ValueError:
        print("Invalid port number provided in environment variable.")
        sys.exit(1)

    max_attempts = int(get_env_var("MAX_ATTEMPTS", "5"))
    retry_interval = int(get_env_var("RETRY_INTERVAL", "2"))

    connect_with_retry(host, port, max_attempts, retry_interval)
